void css_rstat_exit(struct cgroup_subsys_state *css)
{
	struct css_rstat_cpu __percpu *rstat_cpu;
	int cpu;

	if (!css_uses_rstat(css))
		return;

	/*
	 * Disable the updater before flushing to prevent new updates from
	 * leaking in.
	 */
	rstat_cpu = css->rstat_cpu;
	css->rstat_cpu = NULL;
	synchronize_rcu();

	__css_rstat_flush(css, rstat_cpu);

	/* sanity check */
	for_each_possible_cpu(cpu) {
		struct css_rstat_cpu *rstatc = per_cpu_ptr(rstat_cpu, cpu);

		if (WARN_ON_ONCE(rstatc->updated_children != css) ||
		    WARN_ON_ONCE(rstatc->updated_next))
			return;
	}

	if (css_is_self(css)) {
		struct cgroup *cgrp = css->cgroup;

		free_percpu(cgrp->rstat_base_cpu);
		cgrp->rstat_base_cpu = NULL;
	}

	free_percpu(rstat_cpu);
}

